use std::collections::HashSet;impl Solution{pub fn is_rectangle_cover(r:Vec<Vec<i32>>)->bool{let(mut x1,mut y1,mut x2,mut y2)=(i32::MAX,i32::MAX,i32::MIN,i32::MIN);let mut area=0i64;let mut s=HashSet::new();for a in r{x1=x1.min(a[0]);y1=y1.min(a[1]);x2=x2.max(a[2]);y2=y2.max(a[3]);area+=(a[2]-a[0])as i64*(a[3]-a[1])as i64;for p in [(a[0],a[1]),(a[0],a[3]),(a[2],a[1]),(a[2],a[3])]{if !s.insert(p){s.remove(&p);}}}area==(x2-x1)as i64*(y2-y1)as i64&&s==HashSet::from([(x1,y1),(x1,y2),(x2,y1),(x2,y2)])}}
